    busy: false,
    noteId: '',
    noteTitle: '',
    noteBody: '',
    noteFields: { title: null, body: null },
    savedId: '',
  },""",1)
s=s.replace("""        on(Save, {
          target: 'saving',""","""        on(SaveNote, {
          target: 'savingNote',
          assign: (e) => {
            ctx.noteId = e.id
            ctx.noteTitle = e.title
            ctx.noteBody = e.body
            ctx.noteFields = { title: null, body: null }
            ctx.savedId = ''
            ctx.error = null
          },
        }),
        on(Save, {
          target: 'saving',""",1)
s=s.replace("""    adding: {
      invoke""","""    savingNote: {
      invoke: invoke(editNote, {
        input: { id: ctx.noteId, title: ctx.noteTitle, body: ctx.noteBody },
        done: { target: 'idle', assign: () => { ctx.savedId = ctx.noteId; ctx.noteId = ''; ctx.noteTitle = ''; ctx.noteBody = '' } },
        failed: {
          Invalid: { target: 'idle', assign: (e) => { ctx.noteFields = e.fields } },
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND; ctx.noteId = '' } },
          Archived: { target: 'idle', assign: () => { ctx.error = ARCHIVED; ctx.noteId = '' } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    adding: {
      invoke""",1)
open(p,'w').write(s)

p='features/notes/undo.ts'; s=open(p).read()
s=s.replace("title: string; pinned","title: string; body: string; pinned"); open(p,'w').write(s)
p='features/notes/store.ts'; s=open(p).read()
s=s.replace("title, pinned: false","title, body: '', pinned: false"); open(p,'w').write(s)

p='features/notes/server.ts'; s=open(p).read()
s=s.replace("import { adminUsers, addNote,","import { adminUsers, addNote, editNote,")
s=s.replace("number, title: clean, pinned: false","number, title: clean, body: '', pinned: false")
s=s.replace("""    implement(togglePin,""","""    implement(editNote, ({ id, title, body }, { fail, session }) => {
      const items = listOf(session)
      const item = items.find((entry) => entry.id === id)
      if (!item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      const cleanTitle = title.trim()
      const cleanBody = body.replace(/\\r\\n?/g, '\\n').trim()
      const titleError =
        cleanTitle.length === 0 ? 'Write a title first'
          : cleanTitle.length > 60 ? 'Use at most 60 characters'
          : items.some((entry) => entry.id !== id && entry.title.toLowerCase() === cleanTitle.toLowerCase()) ? 'You already have a note with this title'
          : null
      const bodyError = cleanBody.length > 1000 ? 'Use at most 1000 characters in the body' : null
      if (titleError !== null || bodyError !== null)
        return fail('Invalid', { message: 'Check the title and body', fields: { title: titleError, body: bodyError } })
      item.title = cleanTitle
      item.body = cleanBody
      forget(session)
      return view(item)
    }),
    implement(togglePin,""",1)
open(p,'w').write(s)

p='features/notes/text.ts'; s=open(p).read()
s=s.replace("    title: 'Title',\n","    title: 'Title',\n    body: 'Body',\n    saved: 'Saved',\n",1)
s=s.replace("    title: 'Titel',\n","    title: 'Titel',\n    body: 'Inhalt',\n    saved: 'Gespeichert',\n",1)
open(p,'w').write(s)
EOF

